import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { suggestFingering } from '../chords/fingering';
import { GUITAR_MODELS, type GuitarPartId } from '../theory/guitarAnatomy';
import { Fretboard3D, type NeckState } from './fretboard3d';
import { GuitarModel } from './guitarModel';
import { getGuitarLook, type GuitarLook } from './guitarLook';
import { blendPose, clonePose, solveChain, stageContact, type ChainName, type ChainPose, type HandPose, type PreparedHand } from './handModel';
import { HAND_SCALE, STAGE, frettingPose, pluckRig, strumPose, strumRig as makeStrumRig, transitionFrettingPose, type PluckRig, type StrumRig } from './handPoses';
import { HandRig, loadHand } from './hands3d';
import { DEFAULT_STAGE_VIEW, type StageFamily, type StageStep, type StageView } from './stageViews';

/**
 * A complete steel-string guitar with posable hands, built on the shared 3D neck. Stage units match the neck:
 * the nut sits at x = -6, the 12th fret at x = 6 and the saddle at x = 18; +y faces out of the fretboard and
 * +z is the low-E side. Rendering stays on demand: frames run only while something moves.
 */

const L = 24 / 7.6; // guitarAnatomy model units to stage units (steel scale length).
const BODY_X = 7.42;
const TOP_Y = -0.15;
const BOARD_TOP = 0.07;
const BOARD_END = 10.5;
const STRING_NUT_Y = 0.212;
const STRING_SADDLE_Y = 0.226;
const STRUM_REACH = 1.9;
const STRUM_REST = { z: 1.6, y: 0.9 };

const clamp01 = (value: number) => Math.min(1, Math.max(0, value));
const smooth = (value: number) => { const t = clamp01(value); return t * t * (3 - 2 * t); };
const boardHalfWidth = (x: number) => 1.31 + 0.19 * clamp01((x + 6) / 16.5);
export const fretsKey = (frets: readonly (number | null)[]) => frets.map(fret => fret === null ? 'x' : String(fret)).join('.');

/** Replaces extrusion UVs with a planar map of shape coordinates onto [0, 1]. */
function planarUV(geometry: THREE.BufferGeometry, x0: number, width: number, y0: number, height: number): THREE.BufferGeometry {
  const position = geometry.getAttribute('position');
  const uv = new Float32Array(position.count * 2);
  for (let i = 0; i < position.count; i++) {
    uv[i * 2] = (position.getX(i) - x0) / width;
    uv[i * 2 + 1] = (position.getY(i) - y0) / height;
  }
  geometry.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  return geometry;
}

// ---------------------------------------------------------------- strum motion track

interface StrumKey { t: number; z: number; y: number; idle?: boolean }

/** Monotone (Fritsch–Butland) slope, so the pick never overshoots between keyframes. */
function keySlope(keys: readonly StrumKey[], i: number, field: 'z' | 'y'): number {
  if (i <= 0 || i >= keys.length - 1) return 0;
  const a = keys[i - 1], b = keys[i], c = keys[i + 1];
  const h0 = b.t - a.t, h1 = c.t - b.t;
  if (h0 <= 0 || h1 <= 0) return 0;
  const d0 = (b[field] - a[field]) / h0, d1 = (c[field] - b[field]) / h1;
  if (d0 * d1 <= 0) return 0;
  const w1 = 2 * h1 + h0, w2 = h1 + 2 * h0;
  return (w1 + w2) / (w1 / d0 + w2 / d1);
}

function sampleKeys(keys: readonly StrumKey[], t: number, out: { z: number; y: number }): void {
  if (!keys.length) return;
  const last = keys[keys.length - 1];
  if (t <= keys[0].t || keys.length === 1) { out.z = keys[0].z; out.y = keys[0].y; return; }
  if (t >= last.t) { out.z = last.z; out.y = last.y; return; }
  let i = 0;
  while (keys[i + 1].t <= t) i++;
  const a = keys[i], b = keys[i + 1], h = b.t - a.t, s = (t - a.t) / h;
  const s2 = s * s, s3 = s2 * s;
  const h00 = 2 * s3 - 3 * s2 + 1, h10 = s3 - 2 * s2 + s, h01 = -2 * s3 + 3 * s2, h11 = s3 - s2;
  out.z = h00 * a.z + h10 * h * keySlope(keys, i, 'z') + h01 * b.z + h11 * h * keySlope(keys, i + 1, 'z');
  out.y = h00 * a.y + h10 * h * keySlope(keys, i, 'y') + h01 * b.y + h11 * h * keySlope(keys, i + 1, 'y');
}

// ---------------------------------------------------------------- camera presets

interface ViewPreset { target: THREE.Vector3; dir: THREE.Vector3; up: THREE.Vector3; distance: number; halfW: number; halfH: number }
const vec = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
const ROLL_UP = vec(-0.3, 0, 0.95).normalize();
const FRETBOARD_HOME = vec(0.7, 10.8, 9.3);

function viewPreset(view: Exclude<StageView, 'split'>, chordX: number): ViewPreset {
  switch (view) {
    case 'fretboard': return { target: vec(0, 0, 0), dir: FRETBOARD_HOME.clone().normalize(), up: vec(0, 1, 0), distance: FRETBOARD_HOME.length(), halfW: 8.4, halfH: 2.6 };
    case 'player': return { target: vec(5, 0, 0.2), dir: vec(0.2, 0.45, 0.87).normalize(), up: vec(0, 1, 0), distance: 26, halfW: 12.8, halfH: 5.2 };
    case 'guitar': return { target: vec(6.5, -1, 0), dir: vec(0.3, 0.84, 0.45).normalize(), up: ROLL_UP, distance: 50, halfW: 22.5, halfH: 12 };
    case 'fretting': return { target: vec(chordX, 0.2, -0.45), dir: vec(-0.22, 0.9, 0.38).normalize(), up: ROLL_UP, distance: 15, halfW: 4.6, halfH: 3.7 };
    case 'strumming': return { target: vec(13.6, 0.5, 0.4), dir: vec(0.18, 0.88, 0.44).normalize(), up: ROLL_UP, distance: 16, halfW: 5.4, halfH: 4.4 };
    default: return { target: vec(6.2, 0, 1.2), dir: vec(0, 1, 0.14).normalize(), up: ROLL_UP, distance: 46, halfW: 20, halfH: 10 };
  }
}

const MAX_FOV = 50;
/** Fits the preset's half extents into a camera of the given aspect, backing away rather than going fisheye. */
function fitCamera(camera: THREE.PerspectiveCamera, preset: ViewPreset, mirror: number, distanceScale = 1): number {
  const need = Math.max(preset.halfH, preset.halfW / Math.max(camera.aspect, 0.01));
  let distance = preset.distance * distanceScale;
  let fov = THREE.MathUtils.radToDeg(2 * Math.atan(need / distance));
  if (fov > MAX_FOV) { fov = MAX_FOV; distance = need / Math.tan(THREE.MathUtils.degToRad(MAX_FOV / 2)); }
  camera.fov = fov;
  camera.up.set(preset.up.x * mirror, preset.up.y, preset.up.z);
  const target = vec(preset.target.x * mirror, preset.target.y, preset.target.z);
  camera.position.set(preset.dir.x * mirror, preset.dir.y, preset.dir.z).multiplyScalar(distance).add(target);
  camera.lookAt(target);
  camera.updateProjectionMatrix();
  return distance;
}

export type HandStatus = 'loading' | 'ready' | 'failed';
type Frets = readonly (number | null)[];
interface FretChange { start: number; end: number; key: string; frets: Frets }
interface PluckState { rig: PluckRig; thumbRest: Record<number, ChainPose>; thumbPlucked: Record<number, ChainPose> }
interface StringLine { material: THREE.MeshStandardMaterial; meshes: THREE.Mesh[]; radius: number; lastHit: number; glow: number }
interface SplitPane { camera: THREE.PerspectiveCamera; view: 'fretting' | 'strumming'; x: number; y: number; w: number; h: number }

const HAND_CHAINS: readonly ChainName[] = ['thumb', 'index', 'middle', 'ring', 'pinky'];
const TIP = new THREE.Vector3();
const FOCUS = new THREE.Vector3();
const SIZE = new THREE.Vector2();
const Y_AXIS = new THREE.Vector3(0, 1, 0);
const MIX: ChainPose = [0, 0, 0];

function mixChain(a: ChainPose, b: ChainPose, t: number, out: ChainPose): ChainPose {
  for (let k = 0; k < 3; k++) out[k] = a[k] + (b[k] - a[k]) * t;
  return out;
}

/** Where the fretting camera centres a shape: the mean of its pressed frets, or the first position. */
function chordCentre(frets: Frets): number {
  const xs = frets.filter((fret): fret is number => fret !== null && fret > 0)
    .map(fret => STAGE.fretX(fret) - 0.4 * (STAGE.fretX(fret) - STAGE.fretX(fret - 1)));
  return xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : STAGE.fretX(2);
}

/**
 * Field initialisers would run after the base constructor has already called buildScene(), so every field is
 * declared here and initialised in initState() instead.
 */
export class GuitarStage3D extends Fretboard3D {
  /** Called when the hand models finish loading or fail; the stage then shows finger markers instead. */
  declare onHandStatus: ((status: HandStatus) => void) | null;
  private declare look: GuitarLook;
  private declare view: StageView;
  private declare userMoved: boolean;
  private declare zoomScale: number;
  private declare focus: THREE.Vector3;
  private declare splitCamera: THREE.PerspectiveCamera;
  private declare chordX: number;
  private declare cameraTween: { start: number; from: number; to: number } | null;
  private declare clock: () => number;
  private declare reducedMotion: MediaQueryList;
  private declare envTarget: THREE.WebGLRenderTarget | null;
  private declare labModel: GuitarModel;
  private declare diagram: THREE.Group;
  private declare strings: StringLine[];
  private declare handsEnabled: boolean;
  private declare handStatus: HandStatus;
  private declare fretRig: HandRig | null;
  private declare pickRig: HandRig | null;
  private declare fretHand: PreparedHand | null;
  private declare strumHand: PreparedHand | null;
  private declare grip: StrumRig | null;
  private declare pluck: PluckState | null;
  private declare poses: Map<string, HandPose>;
  private declare shown: HandPose | null;
  private declare from: HandPose | null;
  private declare fretQueue: FretChange[];
  private declare fretActive: (FretChange & { target: HandPose }) | null;
  private declare fretTarget: string;
  private declare shownKey: string;
  private declare idleFrets: Frets;
  private declare thumbString: number;
  private declare keys: StrumKey[];
  private declare tip: { z: number; y: number };
  private declare strumOut: HandPose | null;
  private declare pluckOut: HandPose | null;
  private declare handOut: HandPose | null;
  private declare family: StageFamily;
  private declare familyBlend: { from: number; to: number; start: number };
  private declare pluckEvents: { t: number; string: number }[];
  private declare hits: { t: number; string: number }[];
  private declare playingUntil: number;
  private declare shapeQueue: Frets[];
  private declare shapeTimer: number;

  constructor(host: HTMLElement, onPick: (string: number, fret: number) => void, onUnavailable: () => void, descriptionId?: string) {
    super(host, onPick, onUnavailable, descriptionId);
    this.renderer.domElement.setAttribute('aria-label',
      'Interactive 3D guitar with animated hands. Drag to orbit; click a string on the neck to hear it. Use the 2D view for keyboard-accessible frets.');
  }

  protected buildScene(): void {
    this.initState();
    this.buildLighting();
    const posts = this.buildLabGuitar();
    this.buildStageNeck();
    this.buildStrings(posts);
    this.buildTargets(12);
    this.applyView();
    this.loadHands();
  }

  private initState(): void {
    this.onHandStatus = null;
    this.look = getGuitarLook();
    this.view = DEFAULT_STAGE_VIEW;
    this.userMoved = false;
    this.zoomScale = 1;
    this.focus = new THREE.Vector3();
    this.splitCamera = new THREE.PerspectiveCamera(38, 1, 0.5, 300);
    this.chordX = STAGE.fretX(1.5);
    this.cameraTween = null;
    this.clock = () => performance.now() / 1000;
    this.reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
    this.envTarget = null;
    this.diagram = new THREE.Group();
    this.strings = [];
    this.handsEnabled = true;
    this.handStatus = 'loading';
    this.fretRig = null;
    this.pickRig = null;
    this.fretHand = null;
    this.strumHand = null;
    this.grip = null;
    this.pluck = null;
    this.poses = new Map();
    this.shown = null;
    this.from = null;
    this.fretQueue = [];
    this.fretActive = null;
    this.fretTarget = '';
    this.shownKey = '';
    this.idleFrets = [null, null, null, null, null, null];
    this.thumbString = 4;
    this.keys = [];
    this.tip = { ...STRUM_REST };
    this.strumOut = null;
    this.pluckOut = null;
    this.handOut = null;
    this.family = 'strum';
    this.familyBlend = { from: 0, to: 0, start: 0 };
    this.pluckEvents = [];
    this.hits = [];
    this.playingUntil = 0;
    this.shapeQueue = [];
    this.shapeTimer = 0;
    this.camera.near = 0.5;
    this.camera.far = 300;
  }

  private part(geometry: THREE.BufferGeometry, material: THREE.Material | THREE.Material[], x = 0, y = 0, z = 0, parent: THREE.Object3D = this.world): THREE.Mesh {
    this.geometries.add(geometry);
    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.set(x, y, z);
    mesh.receiveShadow = true;
    parent.add(mesh);
    return mesh;
  }

  private physical(parameters: THREE.MeshPhysicalMaterialParameters): THREE.MeshPhysicalMaterial {
    const material = new THREE.MeshPhysicalMaterial(parameters);
    this.materials.add(material);
    return material;
  }

  private buildLighting(): void {
    for (const child of [...this.world.children]) if ((child as THREE.Light).isLight) this.world.remove(child);
    const { renderer } = this;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFShadowMap;
    renderer.toneMapping = THREE.NeutralToneMapping;
    renderer.toneMappingExposure = 1;
    const generator = new THREE.PMREMGenerator(renderer);
    const room = new RoomEnvironment();
    this.envTarget = generator.fromScene(room, 0.04);
    room.dispose();
    generator.dispose();
    this.scene.environment = this.envTarget.texture;
    this.scene.environmentIntensity = 0.65;
    this.world.add(new THREE.HemisphereLight(0xfff2e7, 0x232c27, 0.65));
    const key = new THREE.DirectionalLight(0xfff4e9, 2.5);
    key.position.set(-6, 22, 10);
    key.target.position.set(6, 0, 0);
    key.castShadow = true;
    key.shadow.mapSize.set(2048, 2048);
    Object.assign(key.shadow.camera, { left: -22, right: 22, top: 22, bottom: -22, near: 1, far: 70 });
    key.shadow.camera.updateProjectionMatrix();
    key.shadow.radius = 4;
    key.shadow.normalBias = 0.035;
    key.shadow.bias = -0.0004;
    const rim = new THREE.DirectionalLight(0xcfe2f5, 1.3);
    rim.position.set(14, 8, -14);
    const fill = new THREE.DirectionalLight(0xffe9d2, 0.45);
    fill.position.set(8, 7, 12);
    this.world.add(key, key.target, rim, fill);
  }

  private buildStageNeck(): void {
    const board = this.material(0xffffff, 0, 0.58);
    board.map = this.labModel.woodTexture('ebony');
    const binding = this.material(0xc5ab82, 0, 0.4);
    const back = this.physical({ color: 0xffffff, map: this.labModel.woodTexture('mahogany'), roughness: 0.55, clearcoat: 0.25, clearcoatRoughness: 0.38 });
    const pearl = this.physical({ color: 0xd8cdb5, roughness: 0.22, iridescence: 0.6, iridescenceIOR: 1.6 });
    const metal = this.material(0xb7b4aa, 0.9, 0.26);

    const nutHalf = boardHalfWidth(-6), endHalf = boardHalfWidth(BOARD_END);
    const outline = new THREE.Shape([vec(-6, -nutHalf, 0), vec(BOARD_END, -endHalf, 0), vec(BOARD_END, endHalf, 0), vec(-6, nutHalf, 0)].map(p => new THREE.Vector2(p.x, p.y)));
    const fretboard = this.part(planarUV(new THREE.ExtrudeGeometry(outline, { depth: BOARD_TOP - TOP_Y, bevelEnabled: false }), -6, 16.5, -1.5, 3), [board, binding], 0, TOP_Y, 0);
    fretboard.rotation.x = -Math.PI / 2;
    fretboard.castShadow = true;

    const wire = new THREE.CylinderGeometry(0.032, 0.032, 1, 10, 1);
    for (let fret = 1; fret <= 20; fret++) {
      const x = STAGE.fretX(fret);
      const mesh = this.part(wire, metal, x, BOARD_TOP + 0.012, 0);
      mesh.rotation.x = Math.PI / 2;
      mesh.scale.y = boardHalfWidth(x) * 2;
    }
    const dot = new THREE.CylinderGeometry(0.105, 0.105, 0.008, 24);
    const sideDot = new THREE.CylinderGeometry(0.045, 0.045, 0.01, 16);
    for (const fret of [3, 5, 7, 9, 12, 15, 17, 19]) {
      const x = this.noteX(fret);
      for (const z of fret === 12 ? [-0.48, 0.48] : [0]) this.part(dot, pearl, x, BOARD_TOP, z);
      for (const dx of fret === 12 ? [-0.14, 0.14] : [0]) {
        const side = this.part(sideDot, pearl, x + dx, BOARD_TOP - 0.05, boardHalfWidth(x) + 0.004);
        side.rotation.x = Math.PI / 2;
      }
      const label = this.label(String(fret), x, 0.1, boardHalfWidth(x) + 0.62, 0.42, 0xe8dcc6, this.diagram);
      (label.material as THREE.SpriteMaterial).depthTest = true;
    }
    this.world.add(this.diagram);
    const bone = this.physical({ color: 0xece3cf, roughness: 0.34, clearcoat: 0.3 });
    this.part(new THREE.BoxGeometry(0.11, 0.2, nutHalf * 2 + 0.02), bone, -6.055, 0.12, 0).castShadow = true;

    // Neck back: a half ellipse that thickens toward the body and grows into the heel.
    const segX = 48, segA = 20, x0 = -6.25, x1 = BODY_X + 0.45;
    const positions: number[] = [], uvs: number[] = [], index: number[] = [];
    const profile = (x: number) => {
      const t = clamp01((x + 6) / 13.4);
      return { w: 1.29 + 0.16 * t, d: 0.45 + 0.07 * t + 3.9 * smooth((x - 5.5) / 1.92) };
    };
    for (let i = 0; i <= segX; i++) {
      const x = x0 + (x1 - x0) * i / segX, { w, d } = profile(x);
      for (let j = 0; j <= segA; j++) {
        const a = Math.PI * j / segA;
        positions.push(x, TOP_Y - d * Math.sin(a), w * Math.cos(a));
        uvs.push((x - x0) / 14, j / segA);
      }
    }
    for (let i = 0; i < segX; i++) for (let j = 0; j < segA; j++) {
      const a = i * (segA + 1) + j, b = a + segA + 1;
      index.push(a, a + 1, b, b, a + 1, b + 1);
    }
    const start = positions.length / 3, cap = profile(x0);
    positions.push(x0, TOP_Y, 0);
    uvs.push(0, 0.5);
    for (let j = 0; j <= segA; j++) {
      const a = Math.PI * j / segA;
      positions.push(x0, TOP_Y - cap.d * Math.sin(a), cap.w * Math.cos(a));
      uvs.push(0, j / segA);
      if (j) index.push(start, start + j + 1, start + j);
    }
    const neck = new THREE.BufferGeometry();
    neck.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    neck.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
    neck.setIndex(index);
    neck.computeVertexNormals();
    this.part(neck, back).castShadow = true;
  }

  private buildLabGuitar(): THREE.Vector3[] {
    const model = new GuitarModel('steel', Math.min(8, this.renderer.capabilities.getMaxAnisotropy()));
    this.labModel = model;
    const { nutY } = GUITAR_MODELS.steel;
    const transform = new THREE.Matrix4().set(
      0, -L, 0, -6 + nutY * L,
      0, 0, L, STRING_NUT_Y - 0.732 * L,
      -L, 0, 0, 0,
      0, 0, 0, 1,
    );
    // Keep the playable neck and its picking coordinates; all other visible parts are the actual Lab model.
    const replaced = new Set<GuitarPartId>(['neck', 'fretboard', 'frets', 'nut', 'strings']);
    const headWidth = boardHalfWidth(-6) / (GUITAR_MODELS.steel.nutWidth * L / 2);
    for (const id of ['neck', 'tuners'] as const) model.groups.get(id)!.scale.x = headWidth;
    model.groups.get('bridge')!.position.z = (STRING_SADDLE_Y - STRING_NUT_Y) / L + 0.732 - 0.783;
    model.root.traverse(object => {
      if (!(object instanceof THREE.Mesh)) return;
      const part = object.userData.part as GuitarPartId;
      object.visible = !replaced.has(part) && !(part === 'strapPins' && object.parent === model.groups.get('neck'));
      this.geometries.add(object.geometry);
      for (const material of Array.isArray(object.material) ? object.material : [object.material]) {
        this.materials.add(material);
      }
    });
    for (const [key, texture] of model.textures) this.textures.set(`lab:${key}`, texture);
    model.root.applyMatrix4(transform);
    this.world.add(model.root);
    return [...model.stringPosts].reverse().map(post =>
      post.clone().multiply(new THREE.Vector3(headWidth, 1, 1)).applyMatrix4(transform));
  }

  private buildStrings(posts: THREE.Vector3[]): void {
    const unit = new THREE.CylinderGeometry(1, 1, 1, 8, 1, true);
    this.geometries.add(unit);
    const segment = (material: THREE.Material, radius: number, a: THREE.Vector3, b: THREE.Vector3) => {
      const mesh = new THREE.Mesh(unit, material);
      const direction = b.clone().sub(a);
      mesh.position.copy(a).addScaledVector(direction, 0.5);
      mesh.scale.set(radius, direction.length(), radius);
      mesh.quaternion.setFromUnitVectors(Y_AXIS, direction.normalize());
      mesh.castShadow = true;
      this.world.add(mesh);
      return mesh;
    };
    for (let s = 0; s < 6; s++) {
      const wound = s >= 2;
      const material = this.material(wound ? 0xc8a46a : 0xdedcd6, 0.92, wound ? 0.36 : 0.22);
      const radius = 0.011 + s * 0.0028, z = this.stringZ(s);
      const saddle = vec(STAGE.saddleX, STRING_SADDLE_Y, z);
      const meshes = [
        segment(material, radius, vec(-6, STRING_NUT_Y, z), saddle),
        segment(material, radius, vec(-6.11, STRING_NUT_Y - 0.02, z), posts[s]),
        segment(material, radius, saddle, vec(STAGE.saddleX + 0.21 * L, STRING_SADDLE_Y - 0.048 * L, (s - 2.5) * 0.18 * L)),
      ];
      this.strings.push({ material, meshes, radius, lastHit: -Infinity, glow: 0 });
    }
  }

  // ------------------------------------------------------------ hands

  private loadHands(): void {
    Promise.all([loadHand('left'), loadHand('right')]).then(([left, right]) => {
      if (!this.disposed) this.installHands(left, right);
    }).catch(error => {
      if (this.disposed) return;
      console.warn('3D hands unavailable; the stage shows finger markers instead.', error);
      this.fretRig?.dispose();
      this.pickRig?.dispose();
      this.fretRig = this.pickRig = null;
      this.setHandStatus('failed');
    });
  }

  private installHands(left: PreparedHand, right: PreparedHand): void {
    this.fretHand = left;
    this.strumHand = right;
    this.grip = makeStrumRig(right);
    this.fretRig = new HandRig(left, this.look.skin);
    this.pickRig = new HandRig(right, this.look.skin);
    this.pickRig.attachPick(this.grip.grip);
    this.world.add(this.fretRig.root, this.pickRig.root);
    this.fretQueue = [];
    this.fretActive = null;
    this.shownKey = this.fretTarget = fretsKey(this.idleFrets);
    this.shown = clonePose(this.poseFor(this.idleFrets)!);
    this.fretRig.setPose(this.shown);
    this.strumOut = strumPose(right, this.grip, TIP.set(STAGE.strumX, STRUM_REST.y, STRUM_REST.z), 0);
    this.handOut = clonePose(this.strumOut);
    this.pickRig.setPose(this.strumOut);
    this.setHandStatus('ready');
    this.pumpShapes();
  }

  private setHandStatus(status: HandStatus): void {
    this.handStatus = status;
    this.syncHands();
    this.onHandStatus?.(status);
  }

  getHandStatus(): HandStatus {
    return this.handStatus;
  }

  setHandsVisible(visible: boolean): void {
    this.handsEnabled = visible;
    this.syncHands();
  }

  /** Hands replace the flat finger markers; the plain fretboard view and the hands-off toggle bring markers back. */
  private syncHands(): void {
    const show = this.handsEnabled && this.handStatus === 'ready' && this.view !== 'fretboard';
    if (this.fretRig) this.fretRig.root.visible = show;
    if (this.pickRig) this.pickRig.root.visible = show;
    this.markers.visible = !show;
    this.requestRender();
  }

  private poseFor(frets: Frets): HandPose | null {
    if (!this.fretHand) return null;
    const key = fretsKey(frets);
    let pose = this.poses.get(key);
    if (!pose) {
      pose = frettingPose(this.fretHand, frets, suggestFingering(frets)).pose;
      this.poses.set(key, pose);
    }
    return pose;
  }

  /** Solves upcoming chord shapes one per task so playback never waits on hand placement. */
  prepareShapes(shapes: readonly Frets[]): void {
    this.shapeQueue = shapes.filter(frets => frets.length === 6).map(frets => [...frets]);
    this.pumpShapes();
  }

  private pumpShapes(): void {
    if (this.shapeTimer || this.disposed || !this.fretHand || !this.shapeQueue.length) return;
    this.shapeTimer = window.setTimeout(() => {
      this.shapeTimer = 0;
      const next = this.shapeQueue.shift();
      if (next && !this.disposed) this.poseFor(next);
      this.pumpShapes();
    }, 0);
  }

  // ------------------------------------------------------------ look and views

  protected applyLook(look: GuitarLook): void {
    const mirrorChanged = (look.hand === 'left' ? -1 : 1) !== this.mirror;
    super.applyLook(look);
    this.look = look;
    this.fretRig?.setSkin(look.skin);
    this.pickRig?.setSkin(look.skin);
    if (mirrorChanged) this.applyView();
    this.requestRender();
  }

  setView(view: StageView): void {
    this.view = view;
    this.userMoved = false;
    this.zoomScale = 1;
    this.applyView();
  }

  getView(): StageView {
    return this.view;
  }

  /** Re-frames the cameras and rebuilds orbit controls, whose up axis is fixed when they are created. */
  private applyView(): void {
    this.fitView();
    this.controls.dispose();
    const controls = new OrbitControls(this.camera, this.renderer.domElement);
    controls.enablePan = false;
    controls.enableZoom = false;
    controls.enableDamping = false;
    controls.minPolarAngle = 0.05;
    controls.maxPolarAngle = Math.PI - 0.05;
    controls.enabled = this.view !== 'split';
    controls.target.copy(this.focus);
    let dragging = false;
    controls.addEventListener('start', () => { dragging = true; });
    controls.addEventListener('end', () => { dragging = false; });
    controls.addEventListener('change', () => {
      if (dragging) this.userMoved = true;
      this.requestRender();
    });
    controls.update();
    this.controls = controls;
    this.syncHands();
  }

  private placeCamera(camera: THREE.PerspectiveCamera, preset: ViewPreset): void {
    fitCamera(camera, preset, this.mirror);
    const target = FOCUS.set(preset.target.x * this.mirror, preset.target.y, preset.target.z);
    if (this.zoomScale !== 1) camera.position.sub(target).multiplyScalar(this.zoomScale).add(target);
    if (camera === this.camera) this.focus.copy(target);
  }

  private splitPanes(width: number, height: number): SplitPane[] {
    const gap = 3;
    if (width / height < 1.1) {
      const h = (height - gap) / 2;
      return [
        { camera: this.camera, view: 'fretting', x: 0, y: h + gap, w: width, h },
        { camera: this.splitCamera, view: 'strumming', x: 0, y: 0, w: width, h },
      ];
    }
    const w = (width - gap) / 2, neckLeft = this.mirror === 1;
    return [
      { camera: this.camera, view: 'fretting', x: neckLeft ? 0 : w + gap, y: 0, w, h: height },
      { camera: this.splitCamera, view: 'strumming', x: neckLeft ? w + gap : 0, y: 0, w, h: height },
    ];
  }

  /** Frames the current view for the canvas size; after the user orbits, only the lens adapts. */
  private fitView(): void {
    const { x: width, y: height } = this.renderer.getSize(SIZE);
    if (!width || !height) return;
    if (this.view === 'split') {
      for (const pane of this.splitPanes(width, height)) {
        pane.camera.aspect = pane.w / Math.max(1, pane.h);
        this.placeCamera(pane.camera, viewPreset(pane.view, this.chordX));
      }
    } else {
      this.camera.aspect = width / height;
      const preset = viewPreset(this.view, this.chordX);
      if (this.userMoved) {
        const need = Math.max(preset.halfH, preset.halfW / this.camera.aspect);
        this.camera.fov = Math.min(MAX_FOV, THREE.MathUtils.radToDeg(2 * Math.atan(need / preset.distance)));
        this.camera.updateProjectionMatrix();
        return;
      }
      this.placeCamera(this.camera, preset);
    }
    this.controls.target.copy(this.focus);
  }

  protected resize(): void {
    const { width, height } = this.host.getBoundingClientRect();
    if (!width || !height || this.disposed) return;
    this.renderer.setSize(width, height, false);
    this.fitView();
    this.requestRender();
  }

  zoom(factor: number): void {
    const next = THREE.MathUtils.clamp(this.zoomScale * factor, 0.35, 2.5);
    if (next === this.zoomScale) return;
    const ratio = next / this.zoomScale;
    this.zoomScale = next;
    if (this.userMoved && this.view !== 'split') {
      this.camera.position.sub(this.controls.target).multiplyScalar(ratio).add(this.controls.target);
      this.controls.update();
    } else this.fitView();
    this.requestRender();
  }

  reset(): void {
    this.userMoved = false;
    this.zoomScale = 1;
    this.fitView();
    this.controls.update();
    this.requestRender();
  }

  protected setPickRay(clientX: number, clientY: number): boolean {
    if (this.view !== 'split') return super.setPickRay(clientX, clientY);
    const rect = this.renderer.domElement.getBoundingClientRect();
    if (!rect.width || !rect.height) return false;
    const x = clientX - rect.left, y = rect.height - (clientY - rect.top);
    const pane = this.splitPanes(rect.width, rect.height).find(p => x >= p.x && x <= p.x + p.w && y >= p.y && y <= p.y + p.h);
    if (!pane) return false;
    this.raycaster.setFromCamera(new THREE.Vector2((x - pane.x) / pane.w * 2 - 1, (y - pane.y) / pane.h * 2 - 1), pane.camera);
    return true;
  }

  // ------------------------------------------------------------ playback

  /** Audio clock used by playStep times; animation runs on performance.now() offset to match it. */
  setClock(clock: () => number): void {
    this.clock = clock;
  }

  update(state: NeckState): void {
    super.update(state);
    this.idleFrets = [...state.frets];
    const now = performance.now() / 1000;
    if (now >= this.playingUntil) this.scheduleFrets(this.idleFrets, now + 0.25, 0.3, now);
  }

  playStep(step: StageStep, next: StageStep | null): void {
    if (this.disposed) return;
    const now = performance.now() / 1000;
    const offset = now - this.clock();
    const t = step.at + offset;
    this.playingUntil = t + step.stepSeconds + 0.6;
    if (step.family !== this.family) this.setFamily(step.family);
    if (step.frets) this.scheduleFrets(step.frets, t, step.stepSeconds, now);
    if (next?.frets) this.scheduleFrets(next.frets, next.at + offset, next.stepSeconds, now);
    if (!this.reducedMotion.matches) {
      for (const note of step.notes) this.hits.push({ t: t + note.offset, string: note.stringIndex });
      if (this.family === 'pick') {
        for (const note of step.notes) this.pluckEvents.push({ t: t + note.offset, string: note.stringIndex });
      } else this.strumStep(step, t, now);
    }
    this.requestRender();
  }

  stopPlayback(): void {
    const now = performance.now() / 1000;
    this.playingUntil = 0;
    this.fretQueue = [];
    this.fretTarget = this.fretActive?.key ?? this.shownKey;
    this.pluckEvents = [];
    this.hits = [];
    this.keys = this.keys.filter(key => key.t <= now && !key.idle);
    if (!this.reducedMotion.matches) this.addKeys([], now);
    this.scheduleFrets(this.idleFrets, now + 0.25, 0.3, now);
    this.requestRender();
  }

  setFamily(family: StageFamily): void {
    if (family === this.family) return;
    const now = performance.now() / 1000;
    const weight = this.familyWeight(now);
    this.family = family;
    this.familyBlend = { from: weight, to: family === 'pick' ? 1 : 0, start: now };
    this.requestRender();
  }

  private familyWeight(now: number): number {
    const { from, to, start } = this.familyBlend;
    return this.reducedMotion.matches ? to : from + (to - from) * smooth((now - start) / 0.3);
  }

  /** Queues a chord change that lands just before `at`, lifting the fingers on the way. Repeats are ignored. */
  private scheduleFrets(frets: Frets, at: number, stepSeconds: number, now: number): void {
    const key = fretsKey(frets);
    if (key === this.fretTarget) return;
    this.fretTarget = key;
    const lead = THREE.MathUtils.clamp(0.8 * stepSeconds, 0.1, 0.28);
    const start = Math.max(now, at - lead);
    this.fretQueue.push({ start, end: Math.max(start + 0.06, at - 0.01), key, frets: [...frets] });
    this.fretQueue.sort((a, b) => a.start - b.start);
    this.requestRender();
  }

  private strumStep(step: StageStep, t: number, now: number): void {
    const half = step.stepSeconds / 2, keys: StrumKey[] = [];
    const notes = [...step.notes].sort((a, b) => a.offset - b.offset);
    if ((step.stroke === 'down' || step.stroke === 'up') && notes.length) {
      for (const note of notes) keys.push({ t: t + note.offset, z: STAGE.stringZ(note.stringIndex), y: 0.17 });
      keys.push({ t: t + Math.max(half, notes[notes.length - 1].offset + 0.06), z: step.stroke === 'down' ? -STRUM_REACH : STRUM_REACH, y: 0.5 });
    } else if (step.stroke === 'pluck' && notes.length) {
      for (const note of notes) {
        const z = STAGE.stringZ(note.stringIndex), at = t + note.offset;
        keys.push({ t: at - 0.1, z: z + 0.4, y: 0.35 }, { t: at, z, y: 0.17 }, { t: at + 0.07, z: z - 0.4, y: 0.32 });
      }
    } else {
      // Rests keep the arm swinging in time, clear of the strings, as a steady strummer does.
      const down = step.stroke === 'down' || (step.stroke === 'rest' && step.stepInBar % 2 === 0);
      keys.push({ t, z: 0, y: 0.8 }, { t: t + half, z: down ? -STRUM_REACH : STRUM_REACH, y: 0.8 });
    }
    this.addKeys(keys, now);
  }

  /** Merges new pick keyframes, pinning the current position so the curve never jumps, then appends a return to rest. */
  private addKeys(add: StrumKey[], now: number): void {
    const here = { z: this.tip.z, y: this.tip.y };
    sampleKeys(this.keys, now, here);
    const keys = this.keys.filter(key => !key.idle && key.t > now - 2 && Math.abs(key.t - now) > 0.001);
    keys.push({ t: now, z: here.z, y: here.y });
    for (const key of add) if (key.t > now + 0.001) keys.push(key);
    keys.sort((a, b) => a.t - b.t);
    const merged: StrumKey[] = [];
    for (const key of keys) {
      const last = merged[merged.length - 1];
      if (last && key.t - last.t < 0.001) merged[merged.length - 1] = key;
      else merged.push(key);
    }
    const end = merged[merged.length - 1];
    merged.push({ t: end.t + 0.6, z: end.z, y: Math.max(end.y, 0.5), idle: true }, { t: end.t + 1.2, ...STRUM_REST, idle: true });
    this.keys = merged;
  }

  private ensurePluck(): PluckState | null {
    if (this.pluck || !this.strumHand) return this.pluck;
    const hand = this.strumHand, rig = pluckRig(hand);
    const inverse = rig.pose.quaternion.clone().invert();
    const local = (point: THREE.Vector3) => point.sub(rig.pose.position).applyQuaternion(inverse).multiplyScalar(1 / HAND_SCALE);
    const thumbRest: Record<number, ChainPose> = {}, thumbPlucked: Record<number, ChainPose> = {};
    const restTip = stageContact(hand, rig.pose, 'thumb', HAND_SCALE);
    for (const s of [3, 4, 5]) {
      const target = vec(restTip.x, restTip.y, STAGE.stringZ(s));
      thumbRest[s] = solveChain(hand, 'thumb', local(target.clone()), rig.pose.chains.thumb).pose;
      thumbPlucked[s] = solveChain(hand, 'thumb', local(target.add(vec(0.1, -0.06, -0.42))), thumbRest[s]).pose;
    }
    this.pluck = { rig, thumbRest, thumbPlucked };
    this.pluckOut = clonePose(rig.pose);
    return this.pluck;
  }

  // ------------------------------------------------------------ animation

  private animate(now: number): boolean {
    let active = false;
    if (this.cameraTween) active = this.animateCamera(now) || active;
    if (this.fretRig && this.shown) active = this.animateFretting(now) || active;
    if (this.pickRig) active = this.animatePickHand(now) || active;
    return this.animateStrings(now) || active;
  }

  private animateCamera(now: number): boolean {
    const tween = this.cameraTween!;
    const p = this.reducedMotion.matches ? 1 : clamp01((now - tween.start) / 0.4);
    this.chordX = tween.from + (tween.to - tween.from) * smooth(p);
    if (p >= 1) this.cameraTween = null;
    if (this.view === 'split' || (this.view === 'fretting' && !this.userMoved)) this.fitView();
    return this.cameraTween !== null;
  }

  private animateFretting(now: number): boolean {
    const rig = this.fretRig!, shown = this.shown!;
    while (this.fretQueue.length && this.fretQueue[0].start <= now) {
      const change = this.fretQueue.shift()!;
      const target = this.poseFor(change.frets);
      if (!target) continue;
      this.from = clonePose(shown);
      this.fretActive = { ...change, target };
      this.shownKey = change.key;
      const x = chordCentre(change.frets);
      if (Math.abs(x - (this.cameraTween?.to ?? this.chordX)) > 0.05) this.cameraTween = { start: now, from: this.chordX, to: x };
    }
    const active = this.fretActive;
    if (active && this.from) {
      const p = this.reducedMotion.matches ? 1 : clamp01((now - active.start) / Math.max(0.01, active.end - active.start));
      transitionFrettingPose(this.fretHand!, this.from, active.target, p, shown);
      if (p >= 1) this.fretActive = null;
      rig.setPose(shown);
    }
    return this.fretActive !== null || this.fretQueue.length > 0 || this.cameraTween !== null;
  }

  private animatePickHand(now: number): boolean {
    const hand = this.strumHand, grip = this.grip, strum = this.strumOut, rig = this.pickRig;
    if (!hand || !grip || !strum || !rig || !this.handOut) return false;
    const reduced = this.reducedMotion.matches;
    if (reduced || !this.keys.length) { this.tip.z = STRUM_REST.z; this.tip.y = STRUM_REST.y; }
    else sampleKeys(this.keys, now, this.tip);
    strumPose(hand, grip, TIP.set(STAGE.strumX, this.tip.y, this.tip.z), -0.25 * this.tip.z / STRUM_REACH, strum);
    let active = !reduced && this.keys.length > 0 && now <= this.keys[this.keys.length - 1].t;
    const weight = this.familyWeight(now);
    let pose = strum;
    if (weight > 0 && this.ensurePluck() && this.pluckOut) {
      active = this.animatePluck(now, this.pluckOut) || active;
      pose = weight >= 1 ? this.pluckOut : blendPose(strum, this.pluckOut, weight, this.handOut);
    }
    if (!reduced && this.familyBlend.from !== this.familyBlend.to && now - this.familyBlend.start < 0.3) active = true;
    rig.setPickVisible(weight < 0.5);
    rig.setPose(pose);
    return active;
  }

  /** Fingerstyle: each finger owns a string and the thumb walks the bass strings, flicking through each note. */
  private animatePluck(now: number, out: HandPose): boolean {
    const { rig, thumbRest, thumbPlucked } = this.pluck!;
    out.position.copy(rig.pose.position);
    out.quaternion.copy(rig.pose.quaternion);
    out.forearm.copy(rig.pose.forearm);
    this.pluckEvents = this.pluckEvents.filter(event => event.t > now - 0.4);
    for (const name of HAND_CHAINS) {
      let prev: { t: number; string: number } | null = null, next: { t: number; string: number } | null = null;
      for (const event of this.pluckEvents) {
        if (rig.stringChain[event.string] !== name) continue;
        if (event.t <= now) { if (!prev || event.t > prev.t) prev = event; }
        else if (!next || event.t < next.t) next = event;
      }
      let rest = rig.pose.chains[name], plucked = rig.plucked[name];
      if (name === 'thumb') {
        if (prev && thumbRest[prev.string]) this.thumbString = prev.string;
        rest = thumbRest[this.thumbString] ?? rest;
        if (next && thumbRest[next.string] && next.string !== this.thumbString && now > next.t - 0.15) {
          rest = mixChain(rest, thumbRest[next.string], smooth((now - (next.t - 0.15)) / 0.12), MIX);
        }
        const flick = next && now >= next.t - 0.03 ? next : prev;
        plucked = thumbPlucked[flick?.string ?? this.thumbString] ?? plucked;
      }
      let weight = 0;
      if (next && now >= next.t - 0.03) weight = smooth((now - (next.t - 0.03)) / 0.06);
      if (prev) {
        const age = now - prev.t;
        weight = Math.max(weight, age < 0.03 ? smooth((age + 0.03) / 0.06) : 1 - smooth((age - 0.03) / 0.15));
      }
      mixChain(rest, plucked, weight, out.chains[name]);
    }
    return this.pluckEvents.length > 0;
  }

  private animateStrings(now: number): boolean {
    if (this.hits.length) {
      for (const hit of this.hits) {
        const line = this.strings[hit.string];
        if (hit.t <= now && line) line.lastHit = Math.max(line.lastHit, hit.t);
      }
      this.hits = this.hits.filter(hit => hit.t > now);
    }
    let active = this.hits.length > 0;
    for (const line of this.strings) {
      const age = now - line.lastHit;
      const glow = age >= 0 && age < 1.6 ? Math.exp(-age / 0.35) : 0;
      if (glow > 0) active = true;
      if (glow === line.glow) continue;
      line.glow = glow;
      const main = line.meshes[0];
      main.scale.x = main.scale.z = line.radius * (1 + 1.2 * glow);
      line.material.emissive.setRGB(1, 0.82, 0.54).multiplyScalar(0.6 * glow);
    }
    return active;
  }

  protected renderFrame(time: number): void {
    const active = this.animate(time / 1000);
    const { renderer } = this;
    renderer.shadowMap.autoUpdate = false;
    renderer.shadowMap.needsUpdate = true;
    if (this.view === 'split') {
      const { x: width, y: height } = renderer.getSize(SIZE);
      renderer.setScissorTest(false);
      renderer.setViewport(0, 0, width, height);
      renderer.clear();
      renderer.setScissorTest(true);
      for (const pane of this.splitPanes(width, height)) {
        renderer.setViewport(pane.x, pane.y, pane.w, pane.h);
        renderer.setScissor(pane.x, pane.y, pane.w, pane.h);
        renderer.render(this.scene, pane.camera);
      }
      renderer.setScissorTest(false);
      renderer.setViewport(0, 0, width, height);
    } else renderer.render(this.scene, this.camera);
    if (active) this.requestRender();
  }

  dispose(): void {
    if (this.disposed) return;
    clearTimeout(this.shapeTimer);
    this.fretRig?.dispose();
    this.pickRig?.dispose();
    this.fretRig = this.pickRig = null;
    this.envTarget?.dispose();
    this.envTarget = null;
    super.dispose();
  }
}
