import * as THREE from 'three';
import type { ChordFingering } from '../chords/fingering';
import {
  CHAIN_NAMES, FINGER_CHAIN, basisRotation, blendPose, placeHand, solveChain, solvePickGrip, stageContact, toStage,
  type ChainName, type ChainPose, type ChainTarget, type HandPose, type PickGrip, type PreparedHand,
} from './handModel';

/**
 * Chord shapes to hand poses on the guitar stage. Stage units match the shared 3D neck:
 * x runs from the nut (-6) toward the body, +y is the fretboard normal and +z the low-E side.
 * App string 0 is the high e (z = -1.0); string 5 the low E (z = +1.0).
 */

/** Stage units per metre: a real hand on a neck whose 12th fret sits 12 units from the nut. */
export const HAND_SCALE = 43;

export const STAGE = {
  fretX: (fret: number) => -6 + 24 * (1 - Math.pow(2, -fret / 12)),
  stringZ: (string: number) => (string - 2.5) * 0.4,
  stringY: 0.21,
  /** Neck back profile below the fretboard: a half ellipse. */
  neckCentreY: -0.15,
  neckHalfDepth: 0.45,
  neckHalfWidth: 1.29,
  saddleX: 18,
  strumX: 12.6,
  pluckX: 14.6,
} as const;

/** Where the strumming forearm rests on the upper bout. */
export const STRUM_ELBOW = new THREE.Vector3(20.5, -1.6, 9.4);

const v = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
const FINGERS_DOWN = v(0, -1, 0);

export interface FrettingResult {
  pose: HandPose;
  /** Largest fingertip miss in stage units; under ~0.15 reads as touching the string. */
  error: number;
  /** Stage-space contact targets (point to end segments) per pressing finger, for tests and labels. */
  targets: Partial<Record<ChainName, ChainTarget>>;
}

function fretWidth(fret: number): number {
  return STAGE.fretX(fret) - STAGE.fretX(fret - 1);
}

/**
 * Fingertip targets for a voicing. Each is a short segment in the space behind its fret, so fingers can
 * sit anywhere a guitarist would press; barres lie flat with the tip just past the last covered string.
 */
export function frettingTargets(frets: readonly (number | null)[], fingering: ChordFingering): ChainTarget[] {
  const targets: ChainTarget[] = [];
  const behind = (fret: number, near: number, far: number, y: number, z: number) => {
    const w = fretWidth(fret);
    return { point: v(STAGE.fretX(fret) - near * w, y, z), end: v(STAGE.fretX(fret) - far * w, y, z) };
  };
  for (const finger of [1, 2, 3, 4] as const) {
    const chain = FINGER_CHAIN[finger];
    if (finger === 1 && fingering.barre) {
      // The flat index lies along the fret; its tip may stop anywhere just past the last covered string.
      const { fret, toString } = fingering.barre;
      const x = STAGE.fretX(fret) - 0.3 * fretWidth(fret), z = STAGE.stringZ(toString);
      targets.push({ chain, flat: 0.06, start: [0, 1.45, 0.06], point: v(x, 0.245, z + 0.12), end: v(x, 0.245, z + 0.75) });
      continue;
    }
    const strings = frets.flatMap((fret, string) => fingering.fingers[string] === finger && fret !== null && fret > 0 ? [string] : []);
    if (!strings.length) continue;
    const fret = frets[strings[0]]!;
    if (strings.length > 1) {
      // A small barre with one finger: the pad covers every string up to the tip.
      targets.push({ chain, flat: 0.32, start: [0, 1.3, 0.32], ...behind(fret, 0.15, 0.5, 0.25, STAGE.stringZ(Math.max(...strings)) + 0.12) });
    } else {
      targets.push({ chain, ...behind(fret, 0.06, 0.6, 0.255, STAGE.stringZ(strings[0])) });
    }
  }
  return targets;
}

/** How far a stage point sits inside the neck (fretboard and rounded back), allowing for skin. */
function neckDepth(p: THREE.Vector3, margin = 0.1): number {
  const w = STAGE.neckHalfWidth + margin;
  if (Math.abs(p.z) >= w) return 0;
  const top = 0.2 + margin;
  const back = STAGE.neckCentreY - (STAGE.neckHalfDepth + margin) * Math.sqrt(1 - (p.z / w) ** 2);
  if (p.y >= top || p.y <= back) return 0;
  return Math.min(top - p.y, p.y - back, w - Math.abs(p.z));
}

/**
 * Arched fingers keep their middle joints clear of the strings, a barre finger lies flat and square to its
 * fret, and no joint passes through the neck. The thumb only has to stay outside the neck.
 */
function frettingPenalty(chain: ChainName, joints: THREE.Vector3[], flat: boolean): number {
  if (chain === 'thumb') return 8 * (neckDepth(joints[1]) + neckDepth(joints[2]));
  const inside = 8 * (neckDepth(joints[0]) + neckDepth(joints[1]));
  if (flat) {
    const lift = Math.max(0, joints[2].y - 0.42);
    const skew = joints[3].x - joints[1].x;
    return 6 * lift * lift + 2 * skew * skew + inside;
  }
  const pip = Math.max(0, 0.64 - joints[1].y);
  const dip = Math.max(0, 0.44 - joints[2].y);
  return 4 * (pip * pip + dip * dip) + inside;
}

let frettingBase: THREE.Quaternion | null = null;

export function frettingPose(hand: PreparedHand, frets: readonly (number | null)[], fingering: ChordFingering): FrettingResult {
  frettingBase ??= basisRotation(FINGERS_DOWN, v(0, 1, 0), hand.palmNormal, v(0, 0, 1));
  const targets = frettingTargets(frets, fingering);
  const barre = targets.some(t => t.flat !== undefined && t.chain === 'index');
  const xs = targets.map(t => (t.point.x + (t.end?.x ?? t.point.x)) / 2);
  const meanX = xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : STAGE.fretX(2);
  const thumbZ = 0.32;
  const thumbY = STAGE.neckCentreY - STAGE.neckHalfDepth * Math.sqrt(1 - (thumbZ / STAGE.neckHalfWidth) ** 2) - 0.03;
  const result = placeHand(hand, {
    scale: HAND_SCALE,
    base: frettingBase,
    anchor: 'index',
    xs: [-0.3, 0.3],
    ys: barre ? [0.1, 0.4, 0.7] : [-0.3, 0.1, 0.5],
    zs: barre ? [-1.75, -2.05, -2.35] : [-1.45, -1.8, -2.15],
    rolls: [-0.1, 0.25],
    rollAxis: v(1, 0, 0),
    yaws: [-0.3, 0, 0.3],
    yawAxis: v(0, 0, 1),
    defaultX: STAGE.fretX(1.6),
    targets: [...targets, {
      chain: 'thumb', weight: 0.15, start: [0, 0.25, 0.35],
      point: v(meanX - 0.75, thumbY, thumbZ),
    }],
    forearm: v(0.28, -0.55, -0.79),
    penalty: frettingPenalty,
    rest: (chain, knuckle) => ({ chain, weight: 0, point: v(knuckle.x + 0.25, 1.15, knuckle.z + 1.2), start: [0.05, 0.7, 0.9] }),
  });
  const contacts: Partial<Record<ChainName, ChainTarget>> = {};
  for (const target of targets) contacts[target.chain] = target;
  return { pose: result.pose, error: result.error, targets: contacts };
}

/** Slightly stagger lift/travel/landing inside the existing chord-change window, never after its deadline. */
export function transitionFrettingPose(hand: PreparedHand, from: HandPose, to: HandPose, progress: number, out: HandPose): HandPose {
  const p = THREE.MathUtils.clamp(progress, 0, 1);
  if (p === 0 || p === 1) return blendPose(from, to, p, out);
  const ease = (t: number) => t * t * (3 - 2 * t);
  blendPose(from, to, ease(p), out);
  const rootTravel = from.position.distanceTo(to.position) * 0.4 + from.quaternion.angleTo(to.quaternion);
  for (const [i, name] of (['index', 'middle', 'ring', 'pinky'] as const).entries()) {
    const t = THREE.MathUtils.clamp((p - i * 0.045) / 0.865, 0, 1);
    const a = from.chains[name], b = to.chains[name], result = out.chains[name];
    const travel = Math.min(1, rootTravel + Math.max(...a.map((value, j) => Math.abs(value - b[j]))));
    const lift = Math.sin(Math.PI * t) * travel;
    for (let j = 0; j < 3; j++) {
      const value = a[j] + (b[j] - a[j]) * ease(t) - (j === 1 ? 0.24 : j === 2 ? 0.18 : 0) * lift;
      result[j] = THREE.MathUtils.clamp(value, ...hand.chains[name].limits[j]);
    }
  }
  return out;
}

// ---------------------------------------------------------------- strumming and plucking

export interface StrumRig {
  grip: PickGrip;
  base: THREE.Quaternion;
}

export function strumRig(hand: PreparedHand): StrumRig {
  return {
    grip: solvePickGrip(hand),
    base: basisRotation(FINGERS_DOWN, v(-0.32, 0.12, -1), hand.palmNormal, v(0, -1, 0)),
  };
}

const twistQ = new THREE.Quaternion();
const twistAxis = v(0, 0, 1);
const wristV = new THREE.Vector3();
const ORIGIN = new THREE.Vector3();

/** Places the strumming hand so the pick tip sits at `tip`; `twist` rolls the wrist through the stroke. */
export function strumPose(hand: PreparedHand, rig: StrumRig, tip: THREE.Vector3, twist: number, out?: HandPose): HandPose {
  const pose: HandPose = out ?? {
    position: new THREE.Vector3(), quaternion: new THREE.Quaternion(), forearm: new THREE.Vector3(),
    chains: Object.fromEntries(CHAIN_NAMES.map(name => [name, [...rig.grip.chains[name]]])) as Record<ChainName, ChainPose>,
  };
  pose.quaternion.copy(twistQ.setFromAxisAngle(twistAxis, twist)).multiply(rig.base);
  pose.position.copy(tip).sub(toStage(rig.grip.tip, ORIGIN, pose.quaternion, HAND_SCALE, wristV));
  for (const name of CHAIN_NAMES) {
    const target = pose.chains[name], source = rig.grip.chains[name];
    target[0] = source[0]; target[1] = source[1]; target[2] = source[2];
  }
  toStage(hand.restPosition[hand.wrist], pose.position, pose.quaternion, HAND_SCALE, wristV);
  pose.forearm.subVectors(STRUM_ELBOW, wristV).normalize();
  return pose;
}

export interface PluckRig {
  pose: HandPose;
  /** Follow-through pose per chain after it plucks its string. */
  plucked: Record<ChainName, ChainPose>;
  /** Which chain plucks each app string. */
  stringChain: ChainName[];
  error: number;
}

/** Classical p-i-m-a placement: thumb on the bass strings, fingers on G, B and e. */
export function pluckRig(hand: PreparedHand): PluckRig {
  const x = STAGE.pluckX;
  const z = STAGE.stringZ;
  const result = placeHand(hand, {
    scale: HAND_SCALE,
    base: basisRotation(FINGERS_DOWN, v(-0.12, -0.62, -0.78), hand.palmNormal, v(0, -0.8, 0.6)),
    anchor: 'index',
    ys: [1.2, 1.6, 2.0, 2.4],
    zs: [0.5, 0.95, 1.4, 1.85],
    rolls: [-0.35, -0.12, 0.12, 0.35],
    rollAxis: v(1, 0, 0),
    defaultX: x,
    targets: [
      { chain: 'index', point: v(x, 0.27, z(2)), start: [0, 0.6, 0.8] },
      { chain: 'middle', point: v(x + 0.12, 0.27, z(1)), start: [0, 0.6, 0.8] },
      { chain: 'ring', point: v(x + 0.24, 0.27, z(0)), start: [0, 0.6, 0.8] },
      { chain: 'thumb', point: v(x - 1.05, 0.33, z(4)), start: [0, 0.1, 0.2], weight: 0.6 },
    ],
    forearm: v(0, 0, 1),
    rest: () => [0.22, 0.75, 0.85],
  });
  const pose = result.pose;
  toStage(hand.restPosition[hand.wrist], pose.position, pose.quaternion, HAND_SCALE, wristV);
  pose.forearm.subVectors(STRUM_ELBOW, wristV).normalize();
  const plucked = {} as Record<ChainName, ChainPose>;
  for (const name of CHAIN_NAMES) {
    const [spread, flex1, flex2] = pose.chains[name];
    plucked[name] = name === 'thumb' ? [spread, flex1, flex2] : [spread, Math.min(1.6, flex1 + 0.32), Math.min(1.85, flex2 + 0.42)];
  }
  // The thumb follows through toward the floor, past its string.
  const thumbTip = stageContact(hand, pose, 'thumb', HAND_SCALE).add(v(0.1, -0.06, -0.42));
  const inverse = pose.quaternion.clone().invert();
  const local = thumbTip.sub(pose.position).applyQuaternion(inverse).multiplyScalar(1 / HAND_SCALE);
  plucked.thumb = solveChain(hand, 'thumb', local, pose.chains.thumb).pose;
  return { pose, plucked, stringChain: ['ring', 'middle', 'index', 'thumb', 'thumb', 'thumb'], error: result.error };
}
