import * as THREE from 'three';
import { chainFK, parseHandGlb, poseBones, prepareHand, type HandModelSide, type HandPose, type PickGrip, type PreparedHand } from './handModel';
import { HAND_SCALE } from './handPoses';
import { SKIN_TONES, type SkinTone } from './guitarLook';
import { createHandTextures, handSurfaceCoordinates, nailPlateGeometry } from './handSurface';

/** Skinned, posable hands for the 3D guitar stage; rig maths lives in handModel.ts so tests cover it without WebGL. */

const loading = new Map<HandModelSide, Promise<PreparedHand>>();

/** Fetches and prepares a hand once per page; the prepared arrays are shared by every stage. */
export function loadHand(side: HandModelSide): Promise<PreparedHand> {
  let pending = loading.get(side);
  if (!pending) {
    pending = fetch(`${import.meta.env.BASE_URL}models/hands/${side}.glb`)
      .then(response => {
        if (!response.ok) throw new Error(`Hand model ${side} returned ${response.status}`);
        return response.arrayBuffer();
      })
      .then(buffer => prepareHand(parseHandGlb(buffer).raw, side));
    pending.catch(() => loading.delete(side));
    loading.set(side, pending);
  }
  return pending;
}

const UNIT = new THREE.Vector3(1, 1, 1);
const gripP = [new THREE.Vector3(), new THREE.Vector3(), new THREE.Vector3(), new THREE.Vector3()];
const gripQ = [new THREE.Quaternion(), new THREE.Quaternion(), new THREE.Quaternion(), new THREE.Quaternion()];

function pickShape(): THREE.Shape {
  // A standard 351-style plectrum in metres: a rounded tip and broad shoulders.
  const shape = new THREE.Shape();
  shape.moveTo(0, 0.0145);
  shape.quadraticCurveTo(0.0035, 0.0142, 0.0102, 0.0012);
  shape.quadraticCurveTo(0.0142, -0.0068, 0.0108, -0.0108);
  shape.quadraticCurveTo(0.0064, -0.0142, 0, -0.0128);
  shape.quadraticCurveTo(-0.0064, -0.0142, -0.0108, -0.0108);
  shape.quadraticCurveTo(-0.0142, -0.0068, -0.0102, 0.0012);
  shape.quadraticCurveTo(-0.0035, 0.0142, 0, 0.0145);
  return shape;
}

export class HandRig {
  readonly root = new THREE.Group();
  private readonly bones: THREE.Bone[];
  private readonly mesh: THREE.SkinnedMesh;
  private readonly geometry: THREE.BufferGeometry;
  private readonly skin: THREE.MeshPhysicalMaterial;
  private readonly forearm: THREE.MeshPhysicalMaterial;
  private readonly shadowDepth: THREE.MeshDepthMaterial;
  private readonly nail: THREE.MeshPhysicalMaterial;
  private readonly nailGeometries: THREE.BufferGeometry[] = [];
  private readonly skinTextures: ReturnType<typeof createHandTextures>;
  private readonly outP: THREE.Vector3[];
  private readonly outQ: THREE.Quaternion[];
  private pick: THREE.Mesh | null = null;

  constructor(readonly hand: PreparedHand, tone: SkinTone) {
    const count = hand.boneNames.length;
    this.outP = Array.from({ length: count }, () => new THREE.Vector3());
    this.outQ = Array.from({ length: count }, () => new THREE.Quaternion());
    this.bones = hand.boneNames.map(name => {
      const bone = new THREE.Bone();
      bone.name = name;
      this.root.add(bone);
      return bone;
    });
    const inverses = hand.restPosition.map((position, i) => new THREE.Matrix4().compose(position, hand.restQuaternion[i], UNIT).invert());

    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.Float32BufferAttribute(hand.positions, 3));
    geometry.setAttribute('skinIndex', new THREE.Uint16BufferAttribute(hand.skinIndex, 4));
    geometry.setAttribute('skinWeight', new THREE.Float32BufferAttribute(hand.skinWeight, 4));
    geometry.setIndex(new THREE.BufferAttribute(hand.index, 1));
    geometry.addGroup(0, hand.skinIndexCount, 0);
    geometry.addGroup(hand.skinIndexCount, hand.index.length - hand.skinIndexCount, 1);
    geometry.computeVertexNormals();
    geometry.setAttribute('color', new THREE.Float32BufferAttribute(this.skinShading(geometry), 3));
    const coordinates = handSurfaceCoordinates(hand, geometry.getAttribute('normal'));
    geometry.setAttribute('uv', new THREE.Float32BufferAttribute(coordinates.uv, 2));
    geometry.setAttribute('skinPalm', new THREE.Float32BufferAttribute(coordinates.palm, 1));
    geometry.setAttribute('armOpacity', new THREE.Float32BufferAttribute(coordinates.armOpacity, 1));
    this.skinTextures = createHandTextures(hand, coordinates);
    this.geometry = geometry;

    const palette = SKIN_TONES[tone];
    this.skin = new THREE.MeshPhysicalMaterial({
      color: new THREE.Color(palette.color).multiplyScalar(0.82), vertexColors: true, map: this.skinTextures.dorsal,
      bumpMap: this.skinTextures.bump, bumpScale: 0.00016 * HAND_SCALE, roughness: 0.48, metalness: 0,
      sheen: 0.3, sheenColor: new THREE.Color(palette.sheen), sheenRoughness: 0.55,
      clearcoat: 0.08, clearcoatRoughness: 0.48, specularIntensity: 0.5, envMapIntensity: 0.7,
    });
    this.skin.onBeforeCompile = shader => {
      shader.uniforms.handPalmMap = { value: this.skinTextures.palm };
      shader.vertexShader = 'attribute float skinPalm;\nattribute float armOpacity;\nvarying float vSkinPalm;\nvarying float vArmOpacity;\n' + shader.vertexShader;
      shader.vertexShader = shader.vertexShader.replace('#include <begin_vertex>', '#include <begin_vertex>\nvSkinPalm = skinPalm;\nvArmOpacity = armOpacity;');
      shader.fragmentShader = 'uniform sampler2D handPalmMap;\nvarying float vSkinPalm;\nvarying float vArmOpacity;\n' + shader.fragmentShader;
      shader.fragmentShader = shader.fragmentShader.replace('#include <map_fragment>', `
        vec4 handBack = texture2D(map, vMapUv);
        vec4 handPalm = texture2D(handPalmMap, vMapUv);
        diffuseColor *= mix(handBack, handPalm, smoothstep(-0.25, 0.45, vSkinPalm));
        diffuseColor.a *= vArmOpacity;
      `);
      // Preserve directional modelling on skin without changing the guitar's lights or exposure.
      shader.fragmentShader = shader.fragmentShader.replace('#include <lights_fragment_end>',
        '#include <lights_fragment_end>\nreflectedLight.indirectDiffuse *= 0.5;');
    };
    this.skin.customProgramCacheKey = () => 'guitar-hand-skin-v3';
    this.forearm = this.skin.clone();
    this.forearm.onBeforeCompile = this.skin.onBeforeCompile;
    this.forearm.customProgramCacheKey = this.skin.customProgramCacheKey;
    this.forearm.transparent = true;
    this.forearm.depthWrite = false;
    this.shadowDepth = new THREE.MeshDepthMaterial({ depthPacking: THREE.RGBADepthPacking });
    this.shadowDepth.onBeforeCompile = shader => {
      shader.vertexShader = 'attribute float armOpacity;\nvarying float vArmOpacity;\n' + shader.vertexShader;
      shader.vertexShader = shader.vertexShader.replace('#include <begin_vertex>', '#include <begin_vertex>\nvArmOpacity = armOpacity;');
      shader.fragmentShader = 'varying float vArmOpacity;\n' + shader.fragmentShader;
      shader.fragmentShader = shader.fragmentShader.replace('void main() {', `void main() {
        if (vArmOpacity <= fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233))) * 43758.5453)) discard;
      `);
    };
    this.shadowDepth.customProgramCacheKey = () => 'guitar-hand-shadow-v1';
    this.nail = new THREE.MeshPhysicalMaterial({
      color: new THREE.Color(palette.color).lerp(new THREE.Color(0xedd5cb), 0.55), map: this.skinTextures.nail, roughness: 0.3,
      clearcoat: 0.5, clearcoatRoughness: 0.24, specularIntensity: 0.45, envMapIntensity: 0.6,
    });

    this.mesh = new THREE.SkinnedMesh(geometry, [this.skin, this.forearm]);
    this.mesh.customDepthMaterial = this.shadowDepth;
    this.mesh.frustumCulled = false;
    this.mesh.castShadow = true;
    this.mesh.receiveShadow = true;
    this.root.add(this.mesh);
    // Attached mode with an identity bind matrix: vertices are already in armature space.
    this.mesh.bind(new THREE.Skeleton(this.bones, inverses), new THREE.Matrix4());

    for (const nail of hand.nails) {
      const geometry = nailPlateGeometry(nail);
      this.nailGeometries.push(geometry);
      const cap = new THREE.Mesh(geometry, this.nail);
      cap.castShadow = false;
      this.bones[nail.bone].add(cap);
    }
    this.root.scale.setScalar(HAND_SCALE);
  }

  /** Vertex tints multiply the skin colour: rosier fingertips and knuckles, a paler palm. */
  private skinShading(geometry: THREE.BufferGeometry): Float32Array {
    const { hand } = this;
    const normals = geometry.getAttribute('normal');
    const colors = new Float32Array(normals.count * 3);
    const tips = new Set<number>();
    const knuckles = new Set<number>();
    for (const chain of Object.values(hand.chains)) {
      tips.add(chain.joints[2]); tips.add(chain.joints[3]);
      knuckles.add(chain.joints[1]);
    }
    const palm = hand.palmNormal;
    for (let v = 0; v < normals.count; v++) {
      const bone = hand.skinIndex[v * 4];
      const weight = hand.skinWeight[v * 4];
      let r = 1, g = 1, b = 1;
      if (tips.has(bone)) { r = 1 + 0.03 * weight; g = 1 - 0.09 * weight; b = 1 - 0.1 * weight; }
      else if (knuckles.has(bone)) { g = 1 - 0.04 * weight; b = 1 - 0.05 * weight; }
      const facing = normals.getX(v) * palm.x + normals.getY(v) * palm.y + normals.getZ(v) * palm.z;
      if (facing > 0.2) { const lift = 1 + 0.07 * Math.min(1, (facing - 0.2) / 0.5); r *= lift; g *= lift; b *= lift; }
      colors[v * 3] = r; colors[v * 3 + 1] = g; colors[v * 3 + 2] = b;
    }
    return colors;
  }

  setPose(pose: HandPose): void {
    this.root.position.copy(pose.position);
    this.root.quaternion.copy(pose.quaternion);
    poseBones(this.hand, pose, this.outP, this.outQ);
    for (let i = 0; i < this.bones.length; i++) {
      this.bones[i].position.copy(this.outP[i]);
      this.bones[i].quaternion.copy(this.outQ[i]);
    }
  }

  setSkin(tone: SkinTone): void {
    const palette = SKIN_TONES[tone];
    for (const material of [this.skin, this.forearm]) {
      material.color.setHex(palette.color).multiplyScalar(0.82);
      material.sheenColor.setHex(palette.sheen);
    }
    this.nail.color.setHex(palette.color).lerp(new THREE.Color(0xedd5cb), 0.55);
  }

  /** Holds a plectrum between the thumb pad and the side of the curled index, posed by `grip`. */
  attachPick(grip: PickGrip, color = 0xd9822b): void {
    if (this.pick) return;
    const geometry = new THREE.ExtrudeGeometry(pickShape(), { depth: 0.0008, bevelEnabled: false, curveSegments: 10 });
    geometry.translate(0, 0, -0.0004);
    const material = new THREE.MeshPhysicalMaterial({ color, roughness: 0.38, clearcoat: 0.7, clearcoatRoughness: 0.2, envMapIntensity: 0.8 });
    const pick = new THREE.Mesh(geometry, material);
    pick.castShadow = true;
    // The pick rides on the thumb's distal bone, so it follows the grip exactly as the thumb moves.
    const distal = this.hand.chains.thumb.joints[2];
    chainFK(this.hand, 'thumb', grip.chains.thumb, gripP, gripQ);
    const local = new THREE.Matrix4().compose(gripP[2], gripQ[2], UNIT).invert()
      .multiply(new THREE.Matrix4().compose(grip.centre, grip.quaternion, UNIT));
    local.decompose(pick.position, pick.quaternion, pick.scale);
    this.bones[distal].add(pick);
    this.pick = pick;
  }

  setPickVisible(visible: boolean): void {
    if (this.pick) this.pick.visible = visible;
  }

  dispose(): void {
    this.root.removeFromParent();
    this.geometry.dispose();
    for (const geometry of this.nailGeometries) geometry.dispose();
    this.skin.dispose();
    this.forearm.dispose();
    this.shadowDepth.dispose();
    this.nail.dispose();
    for (const texture of Object.values(this.skinTextures)) texture.dispose();
    if (this.pick) {
      this.pick.geometry.dispose();
      (this.pick.material as THREE.Material).dispose();
    }
    this.mesh.skeleton.dispose();
  }
}
