import * as THREE from 'three';
import type { NailAnchor, PreparedHand } from './handModel';

/** Dorsal intersection at a point on the nail bed, in the distal bone's frame. */
export function nailSurfaceHeight(nail: NailAnchor, x: number, z: number): number {
  const p = nail.surface;
  let height = -Infinity;
  for (let i = 0; i < p.length; i += 9) {
    const ax = p[i], az = p[i + 2], bx = p[i + 3], bz = p[i + 5], cx = p[i + 6], cz = p[i + 8];
    const det = (bz - cz) * (ax - cx) + (cx - bx) * (az - cz);
    if (Math.abs(det) < 1e-12) continue;
    const a = ((bz - cz) * (x - cx) + (cx - bx) * (z - cz)) / det;
    const b = ((cz - az) * (x - cx) + (ax - cx) * (z - cz)) / det;
    const c = 1 - a - b;
    if (Math.min(a, b, c) >= -1e-5) height = Math.max(height, a * p[i + 1] + b * p[i + 4] + c * p[i + 7]);
  }
  if (!Number.isFinite(height)) throw new Error(`Nail on bone ${nail.bone} extends beyond its skin surface`);
  return height;
}

/** A short nail fitted to the actual fingertip, including its tapered sides and curved dorsal surface. */
export function nailPlateGeometry(nail: NailAnchor): THREE.BufferGeometry {
  const segments = 40, rings = 8;
  const positions: number[] = [], uv = [0.5, 0.5], indices: number[] = [];
  const point = (x: number, z: number, radius: number) => {
    x = nail.position.x + x * nail.radius.x;
    z = nail.position.z + z * nail.radius.z;
    const height = nailSurfaceHeight(nail, x, z);
    positions.push(x, height + 0.00006 + (nail.radius.y - 0.00006) * (1 - radius * radius), z);
  };
  point(0, 0, 0);
  for (let ring = 1; ring <= rings; ring++) {
    const radius = ring / rings;
    for (let i = 0; i < segments; i++) {
      const angle = i / segments * Math.PI * 2;
      const c = Math.cos(angle), s = Math.sin(angle);
      const z = Math.sign(s) * Math.abs(s) ** 0.8 * radius;
      const x = Math.sign(c) * Math.abs(c) ** 0.65 * radius * (0.88 + 0.12 * z);
      point(x, z, radius);
      uv.push((x + 1) / 2, (z + 1) / 2);
      const a = 1 + (ring - 1) * segments + i, b = 1 + (ring - 1) * segments + (i + 1) % segments;
      if (ring === 1) indices.push(0, b, a);
      else {
        const p = a - segments, q = b - segments;
        indices.push(p, q, a, a, q, b);
      }
    }
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
}

/** Bind-space UVs keep the skin detail attached to the fingers as the skeleton bends. */
export function handSurfaceCoordinates(hand: PreparedHand, normals: THREE.BufferAttribute | THREE.InterleavedBufferAttribute) {
  const across = hand.palmNormal.clone().cross(hand.forearmAxis).normalize(), along = hand.forearmAxis;
  const wrist = hand.restPosition[hand.wrist], p = new THREE.Vector3();
  let minU = Infinity, maxU = -Infinity, minV = Infinity, maxV = -Infinity;
  for (let i = 0; i < hand.positions.length / 3; i++) {
    p.fromArray(hand.positions, i * 3);
    if (p.clone().sub(wrist).dot(along) > 0.025) continue;
    const u = p.dot(across), v = p.dot(along);
    minU = Math.min(minU, u); maxU = Math.max(maxU, u);
    minV = Math.min(minV, v); maxV = Math.max(maxV, v);
  }
  const width = maxU - minU + 0.008, height = maxV - minV + 0.008;
  const project = (point: THREE.Vector3) => new THREE.Vector2((point.dot(across) - minU + 0.004) / width, (point.dot(along) - minV + 0.004) / height);
  const uv = new Float32Array(normals.count * 2), palm = new Float32Array(normals.count), armOpacity = new Float32Array(normals.count);
  for (let i = 0; i < normals.count; i++) {
    const point = project(p.fromArray(hand.positions, i * 3));
    uv[i * 2] = point.x; uv[i * 2 + 1] = point.y;
    armOpacity[i] = 1 - THREE.MathUtils.smoothstep(p.sub(hand.wristBoundary).dot(along), 0.006, 0.028);
    palm[i] = p.fromBufferAttribute(normals, i).dot(hand.palmNormal);
  }
  return { uv, palm, armOpacity, project, width };
}

export function createHandTextures(hand: PreparedHand, coordinates: ReturnType<typeof handSurfaceCoordinates>) {
  const width = 512, height = 1024;
  const canvas = () => Object.assign(document.createElement('canvas'), { width, height });
  const dorsal = canvas(), palm = canvas(), relief = canvas();
  const back = dorsal.getContext('2d')!, front = palm.getContext('2d')!, bump = relief.getContext('2d')!;
  let seed = 1949;
  const random = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed / 4294967296; };
  const skin = back.createImageData(width, height), pores = bump.createImageData(width, height);
  for (let i = 0; i < skin.data.length; i += 4) {
    const noise = random(), tone = (noise - 0.5) * 7;
    skin.data[i] = 241 + tone; skin.data[i + 1] = 240 + tone; skin.data[i + 2] = 239 + tone;
    skin.data[i + 3] = 255;
    const depth = noise < 0.08 ? 104 : 128 + (noise - 0.5) * 12;
    pores.data[i] = pores.data[i + 1] = pores.data[i + 2] = depth;
    pores.data[i + 3] = 255;
  }
  back.putImageData(skin, 0, 0);
  front.putImageData(skin, 0, 0);
  bump.putImageData(pores, 0, 0);
  const point = (p: THREE.Vector3) => {
    const uv = coordinates.project(p);
    return new THREE.Vector2(uv.x * width, (1 - uv.y) * height);
  };
  const crease = (ctx: CanvasRenderingContext2D, a: THREE.Vector2, b: THREE.Vector2, bend: number, color: string, size = 1.3) => {
    ctx.strokeStyle = color; ctx.lineWidth = size; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(a.x, a.y);
    ctx.quadraticCurveTo((a.x + b.x) / 2 + bend, (a.y + b.y) / 2 + bend * 0.35, b.x, b.y);
    ctx.stroke();
  };
  const wrist = point(hand.restPosition[hand.wrist]);
  for (const [name, chain] of Object.entries(hand.chains)) {
    const start = point(hand.restPosition[chain.joints[0]]);
    if (name !== 'thumb') {
      const end = wrist.clone().lerp(start, 0.25);
      crease(back, start, end, (start.x - wrist.x) * 0.06, 'rgba(255,255,255,.1)', 3);
      crease(back, start.clone().add(new THREE.Vector2(3, 0)), end, 0, 'rgba(126,93,80,.035)', 1.2);
    }
    for (let j = 1; j <= 2; j++) {
      const centre = point(hand.restPosition[chain.joints[j]]);
      const next = point(hand.restPosition[chain.joints[j + 1]]);
      const axis = next.sub(centre).normalize(), cross = new THREE.Vector2(-axis.y, axis.x);
      const half = (name === 'thumb' ? 0.008 : name === 'pinky' ? 0.0045 : 0.006) / coordinates.width * width;
      for (const offset of [-3, 0, 3]) {
        const c = centre.clone().addScaledVector(axis, offset);
        const a = c.clone().addScaledVector(cross, -half), b = c.clone().addScaledVector(cross, half);
        crease(back, a, b, 2, `rgba(125,82,67,${offset === 0 ? 0.24 : 0.1})`);
        crease(front, a, b, -2, 'rgba(148,96,79,.22)');
        crease(bump, a, b, 2, offset === 0 ? '#696969' : '#7b7b7b', 1);
      }
    }
  }
  const at = (name: 'index' | 'middle' | 'ring' | 'pinky' | 'thumb', joint = 0) => point(hand.restPosition[hand.chains[name].joints[joint]]);
  const index = at('index'), pinky = at('pinky'), thumb = at('thumb', 1), middle = at('middle');
  const base = wrist.clone().lerp(middle, 0.27);
  crease(front, index.clone().lerp(wrist, 0.19), pinky.clone().lerp(wrist, 0.27), 13, 'rgba(141,89,70,.22)', 1.8);
  crease(front, index.clone().lerp(wrist, 0.36), pinky.clone().lerp(wrist, 0.55), -12, 'rgba(141,89,70,.2)', 1.6);
  crease(front, index.clone().lerp(thumb, 0.3), base, (thumb.x - middle.x) * 0.45, 'rgba(141,89,70,.22)', 1.8);
  const texture = (image: HTMLCanvasElement, color = true) => {
    const map = new THREE.CanvasTexture(image);
    if (color) map.colorSpace = THREE.SRGBColorSpace;
    map.anisotropy = 4;
    return map;
  };
  const nail = Object.assign(document.createElement('canvas'), { width: 128, height: 256 });
  const ctx = nail.getContext('2d')!;
  const gradient = ctx.createLinearGradient(0, 0, 0, 256);
  gradient.addColorStop(0, '#eadbd4'); gradient.addColorStop(0.3, '#f3ded7'); gradient.addColorStop(0.94, '#f2ddd5'); gradient.addColorStop(1, '#fff4e6');
  ctx.fillStyle = gradient; ctx.fillRect(0, 0, 128, 256);
  ctx.fillStyle = 'rgba(255,248,237,.55)';
  ctx.beginPath(); ctx.ellipse(64, 8, 49, 29, 0, 0, Math.PI * 2); ctx.fill();
  for (let x = 4; x < 128; x += 7) {
    ctx.strokeStyle = 'rgba(255,255,255,.055)'; ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, 256); ctx.stroke();
  }
  return { dorsal: texture(dorsal), palm: texture(palm), bump: texture(relief, false), nail: texture(nail) };
}
